-- 196: One Korean spelling per Hungarian name (국립국어원 헝가리어 표기법).
--
-- Hungarian short a is 어 and á is 아, so Nagy is 너지 and Rajk is 러이크; the
-- prose still carried 나지 임레, 라이크/라지크 라슬로, 파르카시, 레바이, 러요시 딘네시
-- and Nyers as 니에르시 (ny+e is 녜). Given-first leftovers that migration 157
-- missed (임레 너지, 벨라 쿤, 게오르크 루카치, 줄러 호른, 페렌츠 너지 ...) are put
-- family-first with the particle re-chosen (벨라 쿤이 → 쿤 벨러가). Misspelled
-- alias rows are dropped; correctly spelled given-first aliases stay so imported
-- prose still links, as in 157. Evidence excerpts (quoted sources) are left alone.
-- Generated by a one-off script over every Korean text/jsonb column of the
-- person, event, term and curation tables.

BEGIN;
DELETE FROM commulingo_person_aliases WHERE person_id = $q$laszlo-rajk$q$ AND lang = 'ko' AND alias = $q$라이크 라슬로$q$;
DELETE FROM commulingo_person_aliases WHERE person_id = $q$bela-kun$q$ AND lang = 'ko' AND alias = $q$벨라 쿤$q$;
DELETE FROM commulingo_person_aliases WHERE person_id = $q$geza-losonczy$q$ AND lang = 'ko' AND alias = $q$로숀치 게자$q$;
DELETE FROM commulingo_person_aliases WHERE person_id = $q$gyula-horn$q$ AND lang = 'ko' AND alias = $q$귤러 호른$q$;
DELETE FROM commulingo_person_aliases WHERE person_id = $q$rezso-nyers$q$ AND lang = 'ko' AND alias = $q$니에르시 레주$q$;
DELETE FROM commulingo_person_aliases WHERE person_id = $q$andras-hegedus$q$ AND lang = 'ko' AND alias = $q$헤게뒤시 안드라시$q$;
DELETE FROM commulingo_person_aliases WHERE person_id = $q$geza-jeszenszky$q$ AND lang = 'ko' AND alias = $q$예젠스키 게저$q$;
UPDATE commulingo_people SET name_ko = $q$녜르시 레죄$q$ WHERE id = $q$rezso-nyers$q$;
UPDATE commulingo_people SET bio_ko = $q$로숀치 게저는 헝가리 공산주의 운동에서 출발해 당국의 억압과 교조주의를 비판한 언론인이자 정치가였다. 그는 너지 임레의 개혁파와 함께 다당제와 민중운동의 문제를 둘러싼 격변에 개입했고, 1956년 혁명 정부에서 국가장관으로 활동했다. 소련의 개입 뒤 체포되어 재판을 기다리며 단식하다가 감옥에서 사망했으며, 그의 죽음은 너지 임레 집단에 대한 국가 탄압의 일부였다.$q$ WHERE id = $q$geza-losonczy$q$;
UPDATE commulingo_people SET bio_ko = $q$비보 이슈트반은 법학과 정치이론을 바탕으로 헝가리 민주주의와 중동부 유럽의 국가 위기를 분석한 정치사상가였다. 그는 전후 민주적 재편을 위해 행정과 선거 제도 구축에 참여했지만, 공산주의 체제 아래에서는 학문적 자율성과 발언권을 잃었다. 1956년 11월 4일 소련군이 부다페스트를 공격하자 국회의사당에 남은 너지 임레 정부의 마지막 각료로서 「자유와 진실을 위하여」를 썼다. 이후 종신형을 선고받고 1963년 사면으로 석방되었으며, 말년에는 침묵 속에서도 민주주의의 윤리와 책임을 탐구했다.$q$ WHERE id = $q$istvan-bibo$q$;
UPDATE commulingo_people SET bio_ko = $q$도나트 페렌츠는 헝가리 공산주의 운동과 농업정책에 참여한 정치가이자 농업경제 연구자였다. 전후 토지개혁과 집단화 추진에 관여했지만, 1951년 숙청 재판으로 투옥된 뒤 복권되어 당 노선과 국가 폭력의 긴장을 직접 겪었다. 1956년 너지 임레를 지지하며 혁명을 해석하고 소련의 군사 개입을 비판한 그는 너지 임레 재판에서 12년형을 선고받았으나 1960년 석방되었다. 이후 농업경제를 연구하고 1980년대 민주 야당의 대화를 조직했으며, 1989년 법적으로 복권되었다.$q$ WHERE id = $q$ferenc-donath$q$;
UPDATE commulingo_people SET bio_ko = $q$피우메에서 하녀의 사생아로 태어나 이탈리아식으로 체르마니크로 등록되었고, 1927년 타자기 정비공 견습을 시작해 1929년 직인이 되었다. 1931년 불법 공산청년동맹과 당에 입당해 지하활동과 투옥을 겪었다. 1948~50년 내무장관으로서 러이크 라슬로 숙청에 관여했고, 1951년 체포되어 1952년 무기징역을 선고받고 1954년 석방되었다. 1956년 10월 25일 서기장이 되어 11월 1일 소련 측으로 넘어가 진압을 수용하고 너지 임레의 처형을 승인했으며, 수백 명 처형과 수만 명 투옥이 뒤따랐다. 1961년 '우리를 반대하지 않는 자는 우리 편이다'를 제창해 대사면과 개혁을 추진했고, 1988년 사임하고 1989년 사망했다.$q$ WHERE id = $q$janos-kadar$q$;
UPDATE commulingo_people SET bio_ko = $q$데브레첸 출신의 공산주의 법률가로, 1949년 러이크 라슬로 재판의 근거를 의심했다가 모든 당직에서 해임된 후 너지 임레의 개혁파에 합류했다. 1956년 혁명기에는 너지의 개인 비서 겸 총리 비서실장으로 활동했으며, 11월 4일 소련군 진압 후 유고슬라비아 대사관으로 피신했다가 루마니아로 끌려갔다. 1년 넘게 취조에 협력하지 않고 단식 투쟁을 벌여 너지 재판에서 분리 심리되었고, 1958년 4월 24일 너지보다 두 달 먼저 교수형에 처해졌다. 1989년 6월 16일 영웅광장에서 너지·말레테르 등과 함께 재매장되었다.$q$ WHERE id = $q$jozsef-szilagyi$q$;
UPDATE commulingo_people SET bio_ko = $q$부다페스트에서 태어난 유대계 헝가리 언론인으로, 불법 공산주의 운동에 뛰어들어 종전 후 당 기관지 《사바드 네프》의 기자가 되었고, 초기에는 라코시 체제에 충실한 논객이었다. 슬란스키 재판과 모스크바 의사 사건을 목격하며 신념이 흔들렸고, 1955년 러이크 라슬로의 복권을 요구했다가 당에서 제명되었다. 1956년 혁명 당시 너지 임레 측근 중 가장 급진적인 인물로 《머저르 서버처그》를 창간·편집했으며, 소련군 개입 후에도 카다르 정권을 거부하고 지하 신문과 민주독립운동을 이끌다 체포되어 너지, 말레테르와 함께 사형당했다. 1989년 복권되어 같은 날 엄숙히 재매장되었다.$q$ WHERE id = $q$miklos-gimes$q$;
UPDATE commulingo_people SET bio_ko = $q$헝가리 공산당 서기장(1945–1948)과 노동자당(MDP) 서기장·제1서기(1948–1956)로 1948년부터 1956년까지 헝가리를 지배했다. 1925년 체포되어 1926년 8.5년형과 1935년 종신형을 받고 15년 넘게 복역한 뒤 1940년 11월 모스크바에 도착했다. 1945년 귀국 뒤 '살라미 전술'로 민주 정당들을 해체하고 사회민주당을 강제 합병해 일당 지배를 세웠으며, 대량 투옥과 강제노동수용소, 러이크 재판의 책임을 졌다. 1953년 총리직을 너지 임레에게 넘긴 뒤에도 개혁을 방해하다 1956년 7월 18일 해임되었고, 1962년 제명 뒤 크라스노다르·토크마크·아르자마스를 거쳐 1971년 2월 5일 고리키에서 사망했다.$q$ WHERE id = $q$matyas-rakosi$q$;
UPDATE commulingo_people SET bio_ko = $q$녜르시 레죄는 헝가리의 경제학자이자 사회주의권 개혁 정치가로, 계획경제를 사회적 통제와 경제적 효율성의 결합으로 바꾸려 했다. 그는 1968년 신경제메커니즘을 이끈 뒤 정통파의 반발로 영향력을 잃었지만, 개혁의 성과와 한계를 함께 안고 1989년 정치 전환의 중심으로 돌아왔다. 1989년 6월 헝가리 사회주의 노동자당 의장으로 선출되어 집단 지도체제를 이끌었고, 10월 창당된 헝가리 사회당의 초대 의장이 되었다. 그의 경력은 사회주의를 민주화하고 시장기제를 도입하려 한 시도가 당의 해체와 다당제 전환으로 이어진 역사적 긴장을 보여 준다.$q$ WHERE id = $q$rezso-nyers$q$;
UPDATE commulingo_people SET bio_ko = $q$코파치 샨도르는 금속 노동자와 반나치 저항 활동가 출신의 헝가리 경찰 지휘관으로, 국가기구 안에서 개혁의 가능성을 모색했다. 부다페스트 경찰청장으로서 1956년 10월 23일 비무장 시위대에 발포하라는 명령을 거부했고, 봉기 세력과 협력하며 국가근위대 부사령관이 되었다. 그는 체포되어 너지 임레 재판에서 종신형을 선고받았으나 1963년 사면으로 석방되었고, 훗날 회고록으로 혁명의 내부 경험을 증언했다.$q$ WHERE id = $q$sandor-kopacsi$q$;
UPDATE commulingo_people SET moment_ko = $q$1956년 11월 4일, 너지 임레와 함께 소련의 공격을 규탄하는 성명을 작성한 뒤 유고슬라비아 대사관으로 피신했다.$q$ WHERE id = $q$ferenc-donath$q$;
