UPDATE commulingo_people SET activities = $q$[{"endYear":1995,"primary":true,"evidence":[{"claim":"알로이스 모크는 1987년부터 1995년까지 오스트리아 외무장관으로 재임하며 오스트리아의 유럽연합 가입을 이끌었다.","source":"https://en.wikipedia.org/wiki/Alois_Mock","excerpt":"From 1987 to 1995, he was foreign minister, leading Austria into the European Union.","locator":"characters 2148:2232; sha256 d12ffd1010ce529129d52f149a93381d56c6b74ffaf007f068ba2937a5c1cbfb"},{"claim":"외무장관으로서 1989년 헝가리 외무장관 호른 줄러와 함께 철의 장막을 상징적으로 철거하는 등 외교 활동을 수행했다.","source":"https://en.wikipedia.org/wiki/Alois_Mock","excerpt":"On 27 June 1989, together with his Hungarian colleague Gyula Horn, he cut the wires of the Iron Curtain near Sopron at the fortified border to Communist neighbour Hungary.","locator":"characters 2286:2457; sha256 d12ffd1010ce529129d52f149a93381d56c6b74ffaf007f068ba2937a5c1cbfb"}],"relation":"service","startYear":1987,"functionId":"diplomacy","affiliationId":"state-austria","affiliationStatus":"confirmed"}]$q$::jsonb WHERE id = $q$alois-mock$q$;
UPDATE commulingo_people SET activities = $q$[{"endYear":1947,"primary":true,"evidence":[{"claim":"너지 페렌츠는 1946년부터 1947년 강제 사임까지 헝가리 총리를 지냈다.","source":"https://en.wikipedia.org/wiki/Ferenc_Nagy","excerpt":"Ferenc Nagy (8 October 1903 – 12 June 1979) was a Hungarian politician of the Smallholders Party who served as Prime Minister of Hungary from 1946 until his forced resignation in 1947.","locator":"characters 0:184; sha256 c7c13424d592cd53553ee9506ba0478c2370f96cf85389e0ad31bb56c0cf5945"},{"claim":"틸디가 대통령으로 승진한 후 너지가 새 총리가 되었다.","source":"https://en.wikipedia.org/wiki/Ferenc_Nagy","excerpt":"After Hungary's transformation into a republic in February 1946 and Tildy's subsequent elevation to President of Hungary, Nagy became the new premier.","locator":"characters 2996:3146; sha256 c7c13424d592cd53553ee9506ba0478c2370f96cf85389e0ad31bb56c0cf5945"}],"relation":"service","startYear":1946,"functionId":"government","affiliationId":"state-hungary","affiliationStatus":"confirmed"}]$q$::jsonb WHERE id = $q$ferenc-nagy$q$;
UPDATE commulingo_people SET activities = $q$[{"endYear":null,"primary":true,"evidence":[{"claim":"말레테르 팔은 헝가리 군 장교이자 1956년 헝가리 혁명의 주요 인물로, 너지 임레의 세 번째 정부에서 국방장관을 지냈다.","source":"https://en.wikipedia.org/wiki/P%C3%A1l_Mal%C3%A9ter","excerpt":"Pál Maléter (4 September 1917 – 16 June 1958) was a Hungarian military officer and notable figure in the 1956 Hungarian Revolution who served as minister of defence in the third government of Imre Nagy.","locator":"characters 0:202; sha256 404dfe66cf42d98980231b0f9d3e8a8fcd69bf05a1d73b7bd90fa2e35bc1aee3"},{"claim":"1956년 당시 그는 대령으로 부다페스트의 총참모부에서 복무했으며, 봉기 중 킬리안 병영의 부대를 구원하도록 파견되었다.","source":"https://en.wikipedia.org/wiki/P%C3%A1l_Mal%C3%A9ter","excerpt":"In 1956 he was a Colonel and served with the General Staff in Budapest when during the Hungarian Uprising he was sent to relieve a unit at the Kilian barracks with some tanks and a company of officer cadets.","locator":"characters 778:985; sha256 404dfe66cf42d98980231b0f9d3e8a8fcd69bf05a1d73b7bd90fa2e35bc1aee3"}],"relation":"service","startYear":null,"functionId":"military","affiliationId":"state-hungary","affiliationStatus":"confirmed"}]$q$::jsonb WHERE id = $q$pal-maleter$q$;
UPDATE commulingo_people SET activities = $q$[{"endYear":null,"primary":true,"evidence":[{"claim":"1956년 10월 28일 이후 실라지 요제프는 셸 예뇌와 함께 너지 임레 총리 비서실을 조직하고 이를 이끌었다.","source":"https://intezet.nori.gov.hu/nemzeti-sirkert/budapest/uj-koztemeto/szilagyi-jozsef","excerpt":"Október 28. után Széll Jenővel megszervezte, majd vezette Nagy Imre miniszterelnöki titkárságát.","locator":"characters 293:389; sha256 66ecf05deb4bf29d1dd73bdfc0f7c33e22e1ea99ff575c09e1378a70cf0c7581"}],"relation":"employment","startYear":null,"functionId":"government","affiliationId":"state-hungary","affiliationStatus":"confirmed"}]$q$::jsonb WHERE id = $q$jozsef-szilagyi$q$;
UPDATE commulingo_people SET activities = $q$[{"endYear":1989,"primary":true,"evidence":[{"claim":"녜르시 레죄는 1989년 헝가리 사회주의 노동자당 의장을 지냈다.","source":"https://en.wikipedia.org/wiki/Rezs%C5%91_Nyers","excerpt":"was a Hungarian politician and economist who served as President of the Hungarian Socialist Workers' Party (MSZMP) for a few months in 1989","locator":"characters 71:210; sha256 90c7209eeff55d5092c476c87a765f5a09340246329df16b5cc7759b775277f7"}],"relation":"service","startYear":1989,"functionId":"political-leadership","affiliationId":"state-hungary","affiliationStatus":"confirmed"},{"endYear":1962,"primary":false,"evidence":[{"claim":"그는 1960년부터 1962년까지 헝가리 재무장관을 지냈다.","source":"https://en.wikipedia.org/wiki/Rezs%C5%91_Nyers","excerpt":"also served as Minister of Finance from 1960 to 1962","locator":"characters 394:446; sha256 90c7209eeff55d5092c476c87a765f5a09340246329df16b5cc7759b775277f7"}],"relation":"service","startYear":1960,"functionId":"economy","affiliationId":"state-hungary","affiliationStatus":"confirmed"}]$q$::jsonb WHERE id = $q$rezso-nyers$q$;
